function runtimeText(source){
  const t=runtimeTextTranslations[normText(source)];
  if(t && langCode()!=="fa") return t[{en:0,fr:1,ru:2,ar:3,ur:4,zh:5}[langCode()]]||source;
  return translatedSource(source);
}

function normText(v){
  return String(v||"").replace(/\u00a0/g," ").replace(/\s+/g," ").trim();
}
function langCode(){return localStorage.getItem("capitalLang")||"en"}
function lang(){return langs[langCode()]||langs.en}
