function translatedSource(source){
  const key=normText(source);
  const code=langCode();
  if(code==="fa") return source;
  const t=staticTextTranslations[key]||pageTextTranslations[key];
  if(t){
    const idx={en:0,fr:1,ru:2,ar:3,ur:4,zh:5}[code];
    return t[idx]||t[0]||source;
  }
  const k=autoMap[key];
  if(k && langs[code] && langs[code][k]) return langs[code][k];
  return source;
}
function preserveSpace(original,replacement){
  const lead=(original.match(/^\s*/)||[""])[0], tail=(original.match(/\s*$/)||[""])[0];
  return lead+replacement+tail;
}
function translateTextNodes(root){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];
  let n; while((n=walker.nextNode())) nodes.push(n);
  nodes.forEach(node=>{
    const parent=node.parentElement;
    if(!parent || ["SCRIPT","STYLE","NOSCRIPT","OPTION"].includes(parent.tagName)) return;
    if(parent.closest("[data-profile-name]")) return;
    if(parent.closest("[data-no-i18n]")) return;
    if(parent.closest("[data-t]")) return;
    if(!node.__capitalSource) node.__capitalSource=node.nodeValue;
    const source=node.__capitalSource;
    const translated=translatedSource(source);
    if(translated!==source) node.nodeValue=preserveSpace(source,translated);
  });
}

