function translateAttributeSource(source){
  const code=langCode(), t=uiAttributeTranslations[normText(source)];
  if(t && code!=="fa") return t[code]||source;
  return translatedSource(source);
}
function updateDocumentTitle(){
  const p=location.pathname.split("/").pop()||"assets.html";
  const l=lang(), code=langCode();
  const names={en:"CAPITAL",fr:"CAPITAL",ru:"CAPITAL",ar:"CAPITAL",ur:"CAPITAL",zh:"CAPITAL",fa:"CAPITAL"};
  const labels={index:"login",register:"register",assets:"assets",plans:"plans",history:"history",profile:"profile",about:"about",deposit:"deposit",withdraw:"withdraw",market:"market",analysis:"market", "change-password":"changePasswordTitle", notifications:"notificationsTitle"};
  const base=p.replace(".html","");
  if(labels[base] && l[labels[base]]) document.title=names[code]+" | "+l[labels[base]];
}

function translateAttributes(){
  const attrs=["placeholder","title","aria-label","alt"];
  document.querySelectorAll("*").forEach(el=>{
    if(el.closest("[data-no-i18n]")) return;
    attrs.forEach(a=>{
      if(!el.hasAttribute(a)) return;
      const key="__capital_"+a;
      if(!el[key]) el[key]=el.getAttribute(a);
      const source=el[key];
      const t=translateAttributeSource(source);
      if(t!==source) el.setAttribute(a,preserveSpace(source,t));
    });
  });
}
function autoTag(){
  /* Compatibility helper retained for existing pages. The actual translation
     now works directly from original text nodes, including text without data-t. */
  document.querySelectorAll("[data-t]").forEach(el=>{
    if(!el.__capitalSource) el.__capitalSource=el.textContent;
  });
}

